@using System.Linq
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Cms.Web.Common.Views
@using Umbraco.Extensions
@inherits UmbracoViewPage<BlockGridItem<BlogListingBlock>>
@{
    var settings = Model.Settings as BlockSettings;
    var page = Umbraco.AssignedContentItem?.AncestorOrSelf<BlogFrontPage>();
    var posts = page?.Children<BlogPost>()
        .OrderByDescending(post => post.UpdateDate)
        .Select(post =>
        {
            var hero = post.Blocks.Select(item => item.Content).OfType<HeroBlock>().FirstOrDefault();
            return new BlogPostTeaserModel
            {
                Title = post.Name ?? "",
                Url = post.Url(),
                Excerpt = hero?.HeroIntro ?? "",
                ImageUrl = hero?.HeroImage?.GetCropUrl(width: 800, height: 450)
            };
        })
        .ToList() ?? [];

    var model = new BlogListingModel
    {
        Heading = Model.Content.ListingHeading ?? "",
        Intro = Model.Content.ListingIntro ?? "",
        Posts = posts,
        Presentation = new BlockPresentationModel
        {
            BackgroundColor = settings?.BackgroundColor ?? "paper",
            Spacing = settings?.Spacing ?? "medium"
        }
    };
}
@await Component.InvokeAsync("BlogListing", new { model })

